original_code:
// Power Management Controller (PMC)
// Implements: State machine, Clock gating, Voltage scaling, Interrupt handling
// Protocol: Simple power management with sleep, deep-sleep, active, and performance modes
// Constraints: No if/else, no loops, only case statements

module pmc (
    input  logic        clk,           // System clock
    input  logic        rst_n,         // Active-low asynchronous reset
    input  logic        wake_req,      // Wake request from peripheral
    input  logic [1:0]  perf_req,      // Performance level request: 0=low, 1=medium, 2=high, 3=ultra
    input  logic [2:0]  sleep_timeout, // Timeout cycles for sleep entry
    input  logic [1:0]  ext_status,    // External power status (e.g., PMIC ready)

    output logic        clk_cpu_en,    // CPU clock enable
    output logic        clk_periph_en, // Peripheral clock enable
    output logic [1:0]  vdd_level,     // Voltage scaling: 0=0.8V, 1=1.0V, 2=1.2V, 3=1.35V
    output logic        sleep_ack,     // Acknowledge sleep entry
    output logic        wake_ack,      // Acknowledge wakeup
    output logic [1:0]  pmc_status,    // Status output: 0=active, 1=sleep, 2=deep-sleep, 3=performance
    output logic        power_good     // Indicates power rails stable
);

    // State encoding
    typedef enum logic [1:0] {
        ACTIVE      = 2'b00,
        SLEEP       = 2'b01,
        DEEP_SLEEP  = 2'b10,
        PERFORMANCE = 2'b11
    } state_t;

    state_t current_state, next_state;

    // Counters and registers
    logic [2:0]  sleep_cnt;       // Sleep entry counter
    logic [1:0]  vdd_req;         // Requested voltage level
    logic        wake_pending;     // Wake request pending
    logic        clk_switching;    // Clock switching in progress
    logic [1:0]  perf_level;       // Current performance level

    // -----------------------------------------------------------------
    // Block 1: Synchronous State Register (Sequential)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= ACTIVE;
            1'b1: current_state <= next_state;
            default: current_state <= ACTIVE;
        endcase
    end

    // -----------------------------------------------------------------
    // Block 2: Next State Logic (Combinational)
    // Uses nested case statements for state transitions
    // -----------------------------------------------------------------
    always_comb begin
        next_state = current_state;  // Default to stay in current state

        case (current_state)
            ACTIVE: begin
                case (wake_pending)
                    1'b0: begin
                        case (sleep_timeout)
                            3'b000: next_state = SLEEP;      // Timeout expired
                            default: next_state = ACTIVE;     // No timeout, stay active
                        endcase
                    end
                    1'b1: next_state = ACTIVE;  // Wake pending during active
                endcase

                // Performance mode request override
                case (perf_req)
                    2'b11: next_state = PERFORMANCE;
                    default: ;  // Keep previously computed state
                endcase
            end

            SLEEP: begin
                case ({wake_req, wake_pending})
                    2'b00: begin
                        case (sleep_timeout[2])  // Extended sleep check
                            1'b1: next_state = DEEP_SLEEP;
                            default: next_state = SLEEP;
                        endcase
                    end
                    default: next_state = ACTIVE;  // Wake requested
                endcase
            end

            DEEP_SLEEP: begin
                case (wake_req)
                    1'b1: next_state = ACTIVE;
                    default: next_state = DEEP_SLEEP;
                endcase
            end

            PERFORMANCE: begin
                case (perf_req)
                    2'b00: next_state = ACTIVE;
                    2'b01, 2'b10, 2'b11: next_state = PERFORMANCE;
                    default: next_state = ACTIVE;
                endcase
            end

            default: next_state = ACTIVE;
        endcase
    end

    // -----------------------------------------------------------------
    // Block 3: Output and Control Logic (Combinational)
    // Generates all output signals based on current state and inputs
    // -----------------------------------------------------------------
    always_comb begin
        // Default values to avoid latches
        clk_cpu_en     = 1'b0;
        clk_periph_en  = 1'b0;
        vdd_level      = 2'b00;
        sleep_ack      = 1'b0;
        wake_ack       = 1'b0;
        pmc_status     = 2'b00;
        power_good     = 1'b0;
        vdd_req        = 2'b00;

        case (current_state)
            ACTIVE: begin
                clk_cpu_en    = 1'b1;
                clk_periph_en = 1'b1;
                vdd_req       = 2'b01;  // 1.0V
                pmc_status    = 2'b00;
                sleep_ack     = 1'b0;
                wake_ack      = 1'b0;

                case (ext_status)
                    2'b11: power_good = 1'b1;  // External PMIC ready
                    default: power_good = 1'b0;
                endcase

                // Voltage adjustment based on performance request
                case (perf_req)
                    2'b11: vdd_req = 2'b11;  // 1.35V for ultra
                    2'b10: vdd_req = 2'b10;  // 1.2V for high
                    default: vdd_req = 2'b01; // 1.0V for normal
                endcase
            end

            SLEEP: begin
                clk_cpu_en    = 1'b0;
                clk_periph_en = 1'b1;   // Keep peripherals awake for wake detection
                vdd_req       = 2'b00;  // 0.8V
                pmc_status    = 2'b01;
                sleep_ack     = 1'b1;
                wake_ack      = 1'b0;

                case (ext_status[1])
                    1'b1: power_good = 1'b1;
                    default: power_good = 1'b0;
                endcase
            end

            DEEP_SLEEP: begin
                clk_cpu_en    = 1'b0;
                clk_periph_en = 1'b0;
                vdd_req       = 2'b00;  // 0.8V
                pmc_status    = 2'b10;
                sleep_ack     = 1'b1;
                wake_ack      = 1'b0;
                power_good    = 1'b1;   // Power maintained in deep sleep
            end

            PERFORMANCE: begin
                clk_cpu_en    = 1'b1;
                clk_periph_en = 1'b1;
                pmc_status    = 2'b11;
                sleep_ack     = 1'b0;
                wake_ack      = 1'b0;
                power_good    = 1'b1;

                case (perf_level)
                    2'b11: vdd_req = 2'b11;  // Ultra: 1.35V
                    2'b10: vdd_req = 2'b10;  // High: 1.2V
                    2'b01: vdd_req = 2'b01;  // Medium: 1.0V
                    default: vdd_req = 2'b00; // Low: 0.8V
                endcase
            end

            default: ;
        endcase

        // Final voltage assignment (simulate PMIC settling time)
        case (clk_switching)
            1'b1: vdd_level = vdd_req;  // Apply new voltage after switching
            default: vdd_level = 2'b00;
        endcase
    end

    // -----------------------------------------------------------------
    // Block 4: Auxiliary Sequential Logic (Wake/Performance Management)
    // Handles wake pending and performance level tracking
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        // Reset handling using case on rst_n
        case (rst_n)
            1'b0: begin
                wake_pending <= 1'b0;
                clk_switching <= 1'b0;
                perf_level <= 2'b00;
                sleep_cnt <= 3'b000;
            end
            1'b1: begin
                // Wake pending management
                case ({wake_req, wake_ack})
                    2'b10: wake_pending <= 1'b1;
                    2'b01: wake_pending <= 1'b0;
                    default: wake_pending <= wake_pending;
                endcase

                // Clock switching flag
                case (current_state)
                    ACTIVE: begin
                        case (perf_req)
                            2'b11: clk_switching <= 1'b1;
                            default: clk_switching <= 1'b0;
                        endcase
                    end
                    default: clk_switching <= 1'b0;
                endcase

                // Performance level tracking
                case (current_state)
                    PERFORMANCE: begin
                        case (perf_req)
                            2'b00: perf_level <= 2'b00;
                            2'b01: perf_level <= 2'b01;
                            2'b10: perf_level <= 2'b10;
                            2'b11: perf_level <= 2'b11;
                            default: perf_level <= perf_level;
                        endcase
                    end
                    default: perf_level <= 2'b00;
                endcase

                // Sleep counter (increment in sleep states)
                case (current_state)
                    SLEEP: begin
                        case (sleep_cnt)
                            3'b111: sleep_cnt <= 3'b111;
                            default: sleep_cnt <= sleep_cnt + 1'b1;
                        endcase
                    end
                    default: sleep_cnt <= 3'b000;
                endcase
            end
            default: begin
                wake_pending <= 1'b0;
                clk_switching <= 1'b0;
                perf_level <= 2'b00;
                sleep_cnt <= 3'b000;
            end
        endcase
    end

endmodule

