module debouncer_mealy (
    input logic clk,
    input logic rst_n,
    input logic noisy_in,
    input logic [15:0] debounce_time,
    output logic debounced_out
);

typedef enum logic [1:0] {STABLE0, COUNT0, STABLE1, COUNT1} state_t;
state_t state, next_state;
logic [15:0] counter, next_counter;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= STABLE0;
            counter <= 16'b0;
        end
        1'b1: begin
            state <= next_state;
            counter <= next_counter;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_counter = counter;
    debounced_out = 1'b0;

    // Counter update logic
    case (state == COUNT0 || state == COUNT1)
        1'b1: next_counter = counter + 1;
        1'b0: next_counter = 16'b0;
    endcase

    case (state)
        STABLE0: begin
            debounced_out = 1'b0;
            case (noisy_in)
                1'b1: next_state = COUNT0;
            endcase
        end

        COUNT0: begin
            debounced_out = 1'b0;

            case (!noisy_in)
                1'b1: next_state = STABLE0;  // Glitch, go back
            endcase

            case (counter == (debounce_time - 1))
                1'b1: begin
                    next_state = STABLE1;
                    debounced_out = 1'b1;  // Mealy: output high immediately
                end
            endcase
        end

        STABLE1: begin
            debounced_out = 1'b1;
            case (!noisy_in)
                1'b1: next_state = COUNT1;
            endcase
        end

        COUNT1: begin
            debounced_out = 1'b1;

            case (noisy_in)
                1'b1: next_state = STABLE1;  // Glitch, go back
            endcase

            case (counter == (debounce_time - 1))
                1'b1: begin
                    next_state = STABLE0;
                    debounced_out = 1'b0;  // Mealy: output low immediately
                end
            endcase
        end
    endcase
end

endmodule

