module pcie_tlp_decoder (
    input  logic        clk,
    input  logic        rst_n,

    // TLP Input Stream
    input  logic        tlp_valid,
    input  logic [63:0] tlp_data,      // 64-bit TLP data
    input  logic        tlp_start,      // Start of TLP
    input  logic        tlp_end,        // End of TLP
    input  logic [2:0]  tlp_dw_count,   // Double-word count (1-4 DWs for header)

    // Decoded TLP Header Fields
    output logic [7:0]  tlp_fmt_type,   // Format and Type (bits 0-7)
    output logic [9:0]  tlp_length,     // Payload length in DWs
    output logic [15:0] tlp_requester_id, // Requester ID (Bus:Device:Function)
    output logic [15:0] tlp_completer_id, // Completer ID
    output logic [7:0]  tlp_tag,        // Transaction Tag
    output logic [31:0] tlp_address,    // Address for memory transactions
    output logic [31:0] tlp_data_payload, // First 4 bytes of data payload
    output logic [3:0]  tlp_first_be,   // First DW Byte Enables
    output logic [3:0]  tlp_last_be,    // Last DW Byte Enables

    // Transaction Type Flags
    output logic        tlp_mem_read,
    output logic        tlp_mem_write,
    output logic        tlp_cfg_read,
    output logic        tlp_cfg_write,
    output logic        tlp_completion,
    output logic        tlp_completion_data,

    // Error Detection
    output logic        tlp_parity_error,
    output logic        tlp_format_error,
    output logic        tlp_decode_done
);

    // Block 1: TLP State Machine (Sequential)
    typedef enum logic [2:0] {
        IDLE          = 3'b000,
        HEADER_DW0    = 3'b001,
        HEADER_DW1    = 3'b010,
        HEADER_DW2    = 3'b011,
        HEADER_DW3    = 3'b100,
        DATA_PAYLOAD  = 3'b101,
        DECODE_DONE   = 3'b110,
        ERROR         = 3'b111
    } tlp_state_t;

    tlp_state_t current_state, next_state;

    // Header storage registers
    logic [31:0] header_dw0;
    logic [31:0] header_dw1;
    logic [31:0] header_dw2;
    logic [31:0] header_dw3;
    logic [31:0] payload_data;

    // Decoded fields
    logic [7:0]  decoded_fmt_type;
    logic [9:0]  decoded_length;
    logic [15:0] decoded_requester_id;
    logic [15:0] decoded_completer_id;
    logic [7:0]  decoded_tag;
    logic [31:0] decoded_address;
    logic [3:0]  decoded_first_be;
    logic [3:0]  decoded_last_be;
    logic [31:0] decoded_payload;

    // Control signals
    logic [1:0]  header_dw_counter;
    logic        is_3dw_header;
    logic        is_4dw_header;
    logic        has_payload;
    logic [9:0]  payload_dw_remaining;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= IDLE;
            1'b1: current_state <= next_state;
        endcase
    end

    // Block 2: Header Counter and Payload Tracker (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                header_dw_counter <= 2'b0;
                payload_dw_remaining <= 10'b0;
            end
            1'b1: begin
                case (current_state)
                    IDLE: begin
                        case (tlp_start)
                            1'b1: begin
                                header_dw_counter <= 2'b0;
                                payload_dw_remaining <= 10'b0;
                            end
                            default: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                        endcase
                    end

                    HEADER_DW0, HEADER_DW1, HEADER_DW2, HEADER_DW3: begin
                        case (tlp_valid)
                            1'b1: begin
                                header_dw_counter <= header_dw_counter + 2'd1;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                            default: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                        endcase
                    end

                    DATA_PAYLOAD: begin
                        case (tlp_valid)
                            1'b1: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining - 10'd2;  // 2 DWs per cycle
                            end
                            default: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                        endcase
                    end

                    default: begin
                        header_dw_counter <= header_dw_counter;
                        payload_dw_remaining <= payload_dw_remaining;
                    end
                endcase
            end
        endcase
    end

    // Block 3: Header Type Detection (Combinational)
    always_comb begin
        is_3dw_header = 1'b0;
        is_4dw_header = 1'b0;
        has_payload = 1'b0;

        case (header_dw0[30:24])  // Fmt[2:0] and Type[4:0] bits
            8'b000_00000: begin  // MRd - Memory Read (3DW header)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b001_00000: begin  // MRdLk - Memory Read Locked (3DW)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b010_00000: begin  // MWr - Memory Write (3DW with payload)
                is_3dw_header = 1'b1;
                has_payload = 1'b1;
            end
            8'b100_00100: begin  // CfgRd0 - Configuration Read (3DW)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b101_00100: begin  // CfgWr0 - Configuration Write (3DW with payload)
                is_3dw_header = 1'b1;
                has_payload = 1'b1;
            end
            8'b010_01010: begin  // Cpl - Completion without data (3DW)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b010_01011: begin  // CplD - Completion with data (3DW with payload)
                is_3dw_header = 1'b1;
                has_payload = 1'b1;
            end
            8'b010_00001: begin  // MRd64 - Memory Read 64-bit (4DW header)
                is_4dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b011_00001: begin  // MWr64 - Memory Write 64-bit (4DW with payload)
                is_4dw_header = 1'b1;
                has_payload = 1'b1;
            end
            default: begin
                is_3dw_header = 1'b0;
                is_4dw_header = 1'b0;
                has_payload = 1'b0;
            end
        endcase
    end

    // Block 4: State Transition Logic (Case-only Combinational)
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (tlp_start)
                    1'b1: next_state = HEADER_DW0;
                    default: next_state = IDLE;
                endcase
            end

            HEADER_DW0: begin
                case (tlp_valid)
                    1'b1: next_state = HEADER_DW1;
                    default: next_state = HEADER_DW0;
                endcase
            end

            HEADER_DW1: begin
                case (tlp_valid)
                    1'b1: begin
                        case (is_3dw_header)
                            1'b1: begin
                                case (has_payload)
                                    1'b1: next_state = DATA_PAYLOAD;
                                    default: next_state = DECODE_DONE;
                                endcase
                            end
                            default: next_state = HEADER_DW2;
                        endcase
                    end
                    default: next_state = HEADER_DW1;
                endcase
            end

            HEADER_DW2: begin
                case (tlp_valid)
                    1'b1: begin
                        case (is_4dw_header)
                            1'b1: next_state = HEADER_DW3;
                            default: begin
                                case (has_payload)
                                    1'b1: next_state = DATA_PAYLOAD;
                                    default: next_state = DECODE_DONE;
                                endcase
                            end
                        endcase
                    end
                    default: next_state = HEADER_DW2;
                endcase
            end

            HEADER_DW3: begin
                case (tlp_valid)
                    1'b1: begin
                        case (has_payload)
                            1'b1: next_state = DATA_PAYLOAD;
                            default: next_state = DECODE_DONE;
                        endcase
                    end
                    default: next_state = HEADER_DW3;
                endcase
            end

            DATA_PAYLOAD: begin
                case ({tlp_end, (payload_dw_remaining <= 10'd2)})
                    2'b10, 2'b11: next_state = DECODE_DONE;
                    default: next_state = DATA_PAYLOAD;
                endcase
            end

            DECODE_DONE: begin
                case (tlp_end)
                    1'b1: next_state = IDLE;
                    default: next_state = DECODE_DONE;
                endcase
            end

            ERROR: begin
                case (tlp_end)
                    1'b1: next_state = IDLE;
                    default: next_state = ERROR;
                endcase
            end

            default: next_state = ERROR;
        endcase
    end

    // Block 5: Header Data Capture (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                header_dw0 <= 32'b0;
                header_dw1 <= 32'b0;
                header_dw2 <= 32'b0;
                header_dw3 <= 32'b0;
            end
            1'b1: begin
                case (current_state)
                    HEADER_DW0: begin
                        case (tlp_valid)
                            1'b1: header_dw0 <= tlp_data[63:32];  // First DW is upper 32 bits
                            default: header_dw0 <= header_dw0;
                        endcase
                    end

                    HEADER_DW1: begin
                        case (tlp_valid)
                            1'b1: header_dw1 <= tlp_data[31:0];   // Second DW is lower 32 bits
                            default: header_dw1 <= header_dw1;
                        endcase
                    end

                    HEADER_DW2: begin
                        case (tlp_valid)
                            1'b1: header_dw2 <= tlp_data[63:32];
                            default: header_dw2 <= header_dw2;
                        endcase
                    end

                    HEADER_DW3: begin
                        case (tlp_valid)
                            1'b1: header_dw3 <= tlp_data[31:0];
                            default: header_dw3 <= header_dw3;
                        endcase
                    end

                    default: begin
                        header_dw0 <= header_dw0;
                        header_dw1 <= header_dw1;
                        header_dw2 <= header_dw2;
                        header_dw3 <= header_dw3;
                    end
                endcase
            end
        endcase
    end

    // Block 6: Payload Data Capture (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: payload_data <= 32'b0;
            1'b1: begin
                case (current_state)
                    DATA_PAYLOAD: begin
                        case (tlp_valid)
                            1'b1: payload_data <= tlp_data[31:0];  // Capture first 4 bytes of payload
                            default: payload_data <= payload_data;
                        endcase
                    end
                    default: payload_data <= payload_data;
                endcase
            end
        endcase
    end

    // Block 7: Header Field Decoding (Combinational)
    always_comb begin
        decoded_fmt_type = 8'b0;
        decoded_length = 10'b0;
        decoded_requester_id = 16'b0;
        decoded_completer_id = 16'b0;
        decoded_tag = 8'b0;
        decoded_address = 32'b0;
        decoded_first_be = 4'b0;
        decoded_last_be = 4'b0;
        decoded_payload = 32'b0;

        case (current_state)
            DECODE_DONE: begin
                // Fmt and Type fields
                decoded_fmt_type = header_dw0[30:23];

                // Length field (in DWs)
                decoded_length = header_dw0[9:0];

                // Requester ID (Bus:Device:Function)
                decoded_requester_id = header_dw1[31:16];

                case (is_3dw_header)
                    1'b1: begin
                        // Tag field
                        decoded_tag = header_dw1[7:0];

                        // Address for 32-bit addressing
                        decoded_address = {header_dw2[31:2], 2'b0};

                        // First and Last DW Byte Enables
                        decoded_first_be = header_dw1[15:12];
                        decoded_last_be = header_dw1[11:8];

                        // Completer ID for completions
                        case (header_dw0[24:20])  // Type field
                            5'b01010, 5'b01011: begin  // Cpl or CplD
                                decoded_completer_id = header_dw2[31:16];
                            end
                            default: decoded_completer_id = 16'b0;
                        endcase
                    end
                    default: begin  // 4DW header
                        // Tag field
                        decoded_tag = header_dw2[7:0];

                        // Address for 64-bit addressing
                        decoded_address = {header_dw2[31:2], header_dw3[31:0], 2'b0};

                        // First and Last DW Byte Enables
                        decoded_first_be = header_dw2[15:12];
                        decoded_last_be = header_dw2[11:8];
                    end
                endcase

                // Payload data
                decoded_payload = payload_data;
            end

            default: begin
                decoded_fmt_type = decoded_fmt_type;
                decoded_length = decoded_length;
                decoded_requester_id = decoded_requester_id;
                decoded_completer_id = decoded_completer_id;
                decoded_tag = decoded_tag;
                decoded_address = decoded_address;
                decoded_first_be = decoded_first_be;
                decoded_last_be = decoded_last_be;
                decoded_payload = decoded_payload;
            end
        endcase
    end

    // Block 8: Transaction Type Detection (Combinational)
    always_comb begin
        tlp_mem_read = 1'b0;
        tlp_mem_write = 1'b0;
        tlp_cfg_read = 1'b0;
        tlp_cfg_write = 1'b0;
        tlp_completion = 1'b0;
        tlp_completion_data = 1'b0;

        case (decoded_fmt_type)
            8'b000_00000, 8'b001_00000: tlp_mem_read = 1'b1;   // MRd, MRdLk
            8'b010_00000: tlp_mem_write = 1'b1;                // MWr
            8'b100_00100: tlp_cfg_read = 1'b1;                 // CfgRd0
            8'b101_00100: tlp_cfg_write = 1'b1;                // CfgWr0
            8'b010_01010: tlp_completion = 1'b1;               // Cpl
            8'b010_01011: begin                                // CplD
                tlp_completion = 1'b1;
                tlp_completion_data = 1'b1;
            end
            default: begin
                tlp_mem_read = 1'b0;
                tlp_mem_write = 1'b0;
                tlp_cfg_read = 1'b0;
                tlp_cfg_write = 1'b0;
                tlp_completion = 1'b0;
                tlp_completion_data = 1'b0;
            end
        endcase
    end

    // Block 9: Output Assignment and Error Detection (Combinational)
    always_comb begin
        tlp_fmt_type = decoded_fmt_type;
        tlp_length = decoded_length;
        tlp_requester_id = decoded_requester_id;
        tlp_completer_id = decoded_completer_id;
        tlp_tag = decoded_tag;
        tlp_address = decoded_address;
        tlp_data_payload = decoded_payload;
        tlp_first_be = decoded_first_be;
        tlp_last_be = decoded_last_be;
        tlp_decode_done = 1'b0;
        tlp_parity_error = 1'b0;
        tlp_format_error = 1'b0;

        case (current_state)
            DECODE_DONE: begin
                tlp_decode_done = 1'b1;

                // Format error detection
                case ({is_3dw_header, is_4dw_header, (tlp_dw_count >= 3'd3)})
                    3'b100: tlp_format_error = 1'b0;
                    3'b010: tlp_format_error = 1'b0;
                    default: tlp_format_error = 1'b1;
                endcase

                // Parity error detection (simplified - would check ECRC in real design)
                case (^header_dw0 ^ ^header_dw1 ^ ^header_dw2 ^ ^header_dw3)
                    1'b1: tlp_parity_error = 1'b1;
                    default: tlp_parity_error = 1'b0;
                endcase
            end

            ERROR: begin
                tlp_format_error = 1'b1;
                tlp_decode_done = 1'b1;
            end

            default: begin
                tlp_decode_done = 1'b0;
                tlp_parity_error = 1'b0;
                tlp_format_error = 1'b0;
            end
        endcase
    end

endmodule

